# Diagnostic metadata issuer. It performs only bounded reads + CreateNew output.
[CmdletBinding()]param([Parameter(Mandatory=$true)][string]$SourceInputsPath,[Parameter(Mandatory=$true)][string]$SourceInputsHash,[Parameter(Mandatory=$true)][string]$OutputPath,[Parameter(Mandatory=$true)][string]$RunRoot)
$ErrorActionPreference='Stop'
. (Join-Path $PSScriptRoot 'diagnostic-profile.ps1')
if(Test-Path -LiteralPath $OutputPath){throw 'Diagnostic issuer refuses existing metadata'}
if((Get-DiagnosticHash $SourceInputsPath) -cne $SourceInputsHash){throw 'Diagnostic issuer source input drift'}
$si=Get-DiagnosticJson $SourceInputsPath;Assert-CircleDiagnosticSourceInputs (Split-Path -Parent $SourceInputsPath) $si|Out-Null
$at=[DateTimeOffset]::UtcNow.ToString('o');$run=[Guid]::NewGuid().ToString('N')
function New-DiagnosticID([string]$Prefix){$id=$Prefix+'/'+[Guid]::NewGuid().ToString('N');if($id -notmatch ('^'+$Prefix+'/[0-9a-f]{32}$')){throw 'Diagnostic canonical capture ID failure'};return $id}
$capture=[ordered]@{run=1;captureID=(New-DiagnosticID 'capture');imageID=(New-DiagnosticID 'image');provenance=[ordered]@{sourceHash=$si.sourceHash;createdAt=$at;producer='factory/pipeline/pilot-next-source-v1/circle-close-diagnosis-r1/diagnostic-capture-root-v7/issue-circle-diagnostic-metadata-v7.ps1'};plannedHostIdentity='owned-renderer/'+$run;plannedClockIdentity='parent-monotonic-clock/'+$run;measuredHostIdentity=$null;measuredClockIdentity=$null;measurementStatus='pending-actual-launch-joins'}
function Ref([object]$r){[ordered]@{path=[IO.Path]::GetFullPath([string]$r.path);sha256=[string]$r.sha256;bytes=[int64]$r.bytes}}
$m=[ordered]@{kind='factory-prelaunch-capture-metadata-v2';version=2;createdAt=$at;runID=$run;runRoot=[IO.Path]::GetFullPath($RunRoot);expectedCount=1;case=[ordered]@{id=$si.caseID;hash=$si.caseHash};historicalTemplateTupleClosed=$false;recipe=(Ref $si.recipeRef);plan=(Ref $si.planRef);sourceHash=$si.sourceHash;compile=(Ref $si.compileRef);exe=(Ref $si.exeRef);renderer=(Ref $si.rendererRef);sourceBoundCandidateTuple=(Ref $si.bindingRef);candidateTuple=(Ref $si.tupleRef);candidateContext=(Ref $si.contextRef);producedRuntimeModules=$null;serializerControlSha256=$si.serializerControlSha256;frozenTupleBound=$false;hostArguments=@('--factory-capture-lease-seconds=40');captures=@($capture);qualification='diagnostic-native-only-not-qualified'}
$bytes=[Text.UTF8Encoding]::new($true).GetBytes(($m|ConvertTo-Json -Depth 30));$parent=Split-Path -Parent $OutputPath;if(-not(Test-Path -LiteralPath $parent)){New-Item -ItemType Directory -Path $parent|Out-Null};$s=[IO.File]::Open($OutputPath,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::None);try{$s.Write($bytes,0,$bytes.Length);$s.Flush($true)}finally{$s.Dispose()}
